-- Same building may contain several restaurants; the same name may exist elsewhere.
create unique index lunch_restaurants_team_address_name_unique
  on public.lunch_restaurants(team_id, translate(
    -- Same whitespace characters and ASCII case folding as restaurantNameKey().
    regexp_replace(name, U&'[\0009-\000D\0020\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]+', '', 'g'),
    'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz'
  ), translate(
    -- Same whitespace characters and ASCII case folding as restaurantNameKey().
    regexp_replace(address, U&'[\0009-\000D\0020\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]+', '', 'g'),
    'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz'
  ));
drop index public.lunch_restaurants_team_name_unique;

